package got.wildlife;
import got.GOTItems; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.level.Level;
public class GOTOryxEntity extends GOTDefensiveAnimalEntity { public GOTOryxEntity(EntityType<? extends net.minecraft.world.entity.animal.Animal> t,Level l){super(t,l);xpReward=3;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,22).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.ATTACK_DAMAGE,3).add(Attributes.FOLLOW_RANGE,18);} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(net.minecraft.world.item.Items.LEATHER);for(int i=0;i<1+random.nextInt(3)+random.nextInt(looting+1);i++)spawnAtLocation(isOnFire()?GOTItems.DEER_COOKED.get():GOTItems.DEER_RAW.get());} }